package com.aoo.bcg.common.cache;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.Duration;import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.function.Function;
/** Bounded positive/negative cache with per-key single-flight database fallback. */
public final class ProtectedLookupCache<K,V>{private record Entry<V>(Optional<V>value,Instant expiresAt){}private final ConcurrentHashMap<K,Entry<V>>values=new ConcurrentHashMap<>();private final ConcurrentHashMap<K,Object>locks=new ConcurrentHashMap<>();private final AuthoritativeTimeSource time;private final Duration positiveTtl,negativeTtl;private final int maximumEntries;public ProtectedLookupCache(AuthoritativeTimeSource time,Duration positiveTtl,Duration negativeTtl,int maximumEntries){this.time=Objects.requireNonNull(time);this.positiveTtl=positiveTtl;this.negativeTtl=negativeTtl;this.maximumEntries=maximumEntries;if(positiveTtl.isNegative()||positiveTtl.isZero()||negativeTtl.isNegative()||negativeTtl.isZero()||maximumEntries<=0)throw new IllegalArgumentException("invalid cache policy");}public Optional<V>get(K key,Function<K,Optional<V>>loader){Instant now=time.now();Entry<V>entry=values.get(key);if(entry!=null&&entry.expiresAt().isAfter(now))return entry.value();Object lock=locks.computeIfAbsent(key,ignored->new Object());try{synchronized(lock){now=time.now();entry=values.get(key);if(entry!=null&&entry.expiresAt().isAfter(now))return entry.value();Optional<V>loaded=Objects.requireNonNull(loader.apply(key));if(values.size()>=maximumEntries)evictExpiredOrOne(now);values.put(key,new Entry<>(loaded,now.plus(loaded.isPresent()?positiveTtl:negativeTtl)));return loaded;}}finally{locks.remove(key,lock);}}public void invalidate(K key){values.remove(Objects.requireNonNull(key));}public int size(){return values.size();}private void evictExpiredOrOne(Instant now){values.entrySet().removeIf(entry->!entry.getValue().expiresAt().isAfter(now));if(values.size()>=maximumEntries)values.keySet().stream().findFirst().ifPresent(values::remove);}}
